/**
 * Keeps installed copies of the app up to date.
 *
 * The service worker (generated by vite-plugin-pwa, with skipWaiting and
 * clientsClaim) downloads a new version in the background and takes over the
 * page; the page then still runs the old code until it reloads. We reload only
 * once the user has left the app (it is hidden), so nothing on screen is ever
 * interrupted, and never while a sign-in or password-reset screen is open.
 * Installed apps (iPhone especially) resume without reloading, so every return
 * to the app also checks for a new version.
 *
 * "A new version took over" is the container's controllerchange event, not
 * workbox-window's update events, which stop reporting after a failed update.
 */

let pending = false;
let held = 0;

/** Reload into a new version only when it is waiting, nothing holds it, and the app is out of sight. */
export function shouldReload(state: { pending: boolean; held: number; visibility: DocumentVisibilityState }): boolean {
  return state.pending && state.held === 0 && state.visibility === 'hidden';
}

function reloadIfSafe() {
  if (shouldReload({ pending, held, visibility: document.visibilityState })) location.reload();
}

/**
 * Keeps the page from reloading into a new version while some screen would
 * lose what the user is doing (e.g. typing the code from a password-reset
 * email). Returns the release function, so it fits a useEffect.
 */
export function holdUpdates(): () => void {
  held++;
  let released = false;
  return () => {
    if (released) return;
    released = true;
    held--;
    reloadIfSafe();
  };
}

export function keepUpToDate(): void {
  if (!('serviceWorker' in navigator)) return;
  const sw = navigator.serviceWorker;
  // The first install also "takes over" a page that had no worker: that is not a new version.
  let hadController = !!sw.controller;
  sw.addEventListener('controllerchange', () => {
    if (hadController) pending = true;
    hadController = true;
    reloadIfSafe();
  });

  let registration: ServiceWorkerRegistration | undefined;
  document.addEventListener('visibilitychange', () => {
    reloadIfSafe();
    // Offline, or the server is unreachable: try again next time.
    if (document.visibilityState === 'visible') registration?.update().catch(() => {});
  });

  const register = () => {
    const base = import.meta.env.BASE_URL;
    sw.register(`${base}sw.js`, { scope: base }).then(
      (r) => (registration = r),
      // Blocked or unsupported: the app still works, just without offline use or updates.
      () => {},
    );
  };
  if (document.readyState === 'complete') register();
  else window.addEventListener('load', register, { once: true });
}
